  /**
   * 初始化 Agent
   */
  async init() {
    this.logger.info('正在初始化 Resonix Agent...');

    // 连接所有 MCP 服务器
    await this.mcp.connectAll();

    // 初始化记忆系统
    await this.memory.init();

    // 注册内置技能
    this.skills.registerBuiltinSkills();

    // 加载历史记忆
    const memories = await this.memory.recallRecent(10);
    if (memories.length > 0) {
      this.logger.info('已加载 ' + memories.length + ' 条历史记忆');
    }

    this.logger.success('Resonix Agent 初始化完成!');
    this._printStatus();
  }

  /**
   * 运行 Agent 主循环
   */
  async run(userMessage) {
    // 添加用户消息到历史
    this.conversationHistory.push({
      role: 'user',
      content: userMessage
    });

    // 检查是否需要先回忆相关记忆
    const relevantMemories = await this.memory.search(userMessage);
    if (relevantMemories.length > 0) {
      const memoryContext = '相关记忆:\n' + relevantMemories.map(m => '- ' + m.content).join('\n');
      this.conversationHistory.push({
        role: 'system',
        content: memoryContext
      });
    }

    let iteration = 0;
    let finalResponse = '';

    while (iteration < this.maxIterations) {
      iteration++;

      try {
        // 获取 MCP 工具列表
        const mcpTools = this.mcp.getToolsAsOpenAIFormat();

        // 调用 LLM
        const response = await this.llm.chat.completions.create({
          model: this.model,
          messages: [
            { role: 'system', content: this.systemPrompt },
            ...this.conversationHistory
          ],
          tools: mcpTools.length > 0 ? mcpTools : undefined,
          tool_choice: mcpTools.length > 0 ? 'auto' : undefined,
          temperature: 0.7,
          max_tokens: 4096
        });

        const message = response.choices[0].message;
        this.conversationHistory.push(message);

        // 如果没有工具调用，返回最终响应
        if (!message.tool_calls || message.tool_calls.length === 0) {
          finalResponse = message.content;
          break;
        }

        // 处理工具调用
        for (const toolCall of message.tool_calls) {
          const toolName = toolCall.function.name;
          const toolArgs = JSON.parse(toolCall.function.arguments);

          this.logger.toolCall(toolName, toolArgs);

          try {
            // 解析服务器名和工具名
            const [serverName, ...rest] = toolName.split('__');
            const actualToolName = rest.join('__');

            let result;
            // 优先使用 MCP 工具
            if (this.mcp.clients.has(serverName)) {
              result = await this.mcp.callTool(serverName, actualToolName, toolArgs);
            } else {
              // 尝试内置技能
              result = await this.skills.execute(toolName, toolArgs);
            }

            const resultStr = typeof result === 'string' ? result : JSON.stringify(result);
            this.logger.toolResult(toolName, resultStr);

            this.conversationHistory.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              content: resultStr
            });

            // 重要结果存入记忆
            if (this._isWorthRemembering(toolName, resultStr)) {
              await this.memory.remember({
                type: 'tool_result',
                tool: toolName,
                query: userMessage,
                result: resultStr.substring(0, 500)
              });
            }

          } catch (error) {
            this.logger.error('工具调用失败 ' + toolName + ': ' + error.message);
            this.conversationHistory.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              content: '错误: ' + error.message
            });
          }
        }

      } catch (error) {
        this.logger.error('LLM 调用失败: ' + error.message);
        finalResponse = '抱歉，处理时出现错误: ' + error.message;
        break;
      }
    }

    if (iteration >= this.maxIterations) {
      finalResponse = '已达到最大迭代次数，任务可能未完全完成。';
    }

    // 保存对话到记忆
    await this.memory.remember({
      type: 'conversation',
      user: userMessage,
      assistant: finalResponse
    });

    return finalResponse;
  }

  /**
   * 判断结果是否值得记忆
   */
  _isWorthRemembering(toolName, result) {
    const memorableTools = [
      'file_write',
      'shell_execute',
      'code_execute'
    ];
    return memorableTools.some(t => toolName.startsWith(t));
  }

  /**
   * 打印状态
   */
  _printStatus() {
    const status = this.mcp.getStatus();
    console.log('\n' + chalk.cyan('========================================'));
    console.log(chalk.cyan('  Resonix Agent 状态面板'));
    console.log(chalk.cyan('========================================'));
    for (const [name, info] of Object.entries(status)) {
      const icon = info.status === 'connected' ? chalk.green('OK') : chalk.red('FAIL');
      console.log('  ' + icon + ' ' + chalk.bold(name) + ' (' + info.tools + ' tools) - ' + info.description);
    }
    console.log(chalk.cyan('========================================') + '\n');
  }

  /**
   * 关闭 Agent
   */
  async shutdown() {
    this.logger.info('正在关闭 Resonix Agent...');
    await this.mcp.disconnectAll();
    await this.memory.close();
    this.logger.success('Resonix Agent 已关闭');
  }
}

#!/usr/bin/env node

/**
 * Resonix Super Agent - 主入口
 * 交互式命令行 Agent
 */

import { ResonixAgent } from './agent.js';
import chalk from 'chalk';
import readline from 'readline';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function printBanner() {
  console.log('');
  console.log(chalk.cyan('  ╔══════════════════════════════════════════╗'));
  console.log(chalk.cyan('  ║') + chalk.bold.white('       R E S O N I X   A G E N T        ') + chalk.cyan('║'));
  console.log(chalk.cyan('  ║') + chalk.gray('     Professional AI Agent with MCP       ') + chalk.cyan('║'));
  console.log(chalk.cyan('  ╚══════════════════════════════════════════╝'));
  console.log('');
  console.log(chalk.gray('  命令:'));
  console.log(chalk.gray('    /status   - 查看 MCP 服务器状态'));
  console.log(chalk.gray('    /memory   - 查看记忆统计'));
  console.log(chalk.gray('    /skills   - 查看可用技能'));
  console.log(chalk.gray('    /clear    - 清除对话历史'));
  console.log(chalk.gray('    /help     - 显示帮助'));
  console.log(chalk.gray('    /exit     - 退出 Agent'));
  console.log('');
}

async function main() {
  printBanner();

  const agent = new ResonixAgent({
    name: 'Resonix',
    model: process.env.OPENAI_MODEL || 'gpt-4o'
  });

  console.log(chalk.yellow('正在初始化 Agent...'));
  try {
    await agent.init();
  } catch (error) {
    console.error(chalk.red('初始化失败: ' + error.message));
    console.log(chalk.yellow('提示: 请检查 .env 文件中的 API Key 配置'));
    console.log(chalk.yellow('你可以复制 .env.example 为 .env 并填入你的 API Key'));
  }

  console.log(chalk.green('
Agent 已就绪! 输入你的问题开始对话。
'));

  const prompt = () => {
    rl.question(chalk.bold.cyan('You> '), async (input) => {
      const trimmed = input.trim();

      if (!trimmed) {
        prompt();
        return;
      }

      // 处理命令
      if (trimmed.startsWith('/')) {
        const cmd = trimmed.toLowerCase();

        switch (cmd) {
          case '/exit':
          case '/quit':
            console.log(chalk.yellow('
正在关闭...'));
            await agent.shutdown();
            console.log(chalk.green('再见!'));
            process.exit(0);
            break;

          case '/status':
            const status = agent.mcp.getStatus();
            console.log(chalk.cyan('
=== MCP 服务器状态 ==='));
            for (const [name, info] of Object.entries(status)) {
              const icon = info.status === 'connected' ? chalk.green('OK') : chalk.red('FAIL');
              console.log('  ' + icon + ' ' + name + ' (' + info.tools + ' tools) - ' + info.description);
            }
            console.log('');
            break;

          case '/memory':
            const stats = agent.memory.getStats();
            console.log(chalk.cyan('
=== 记忆统计 ==='));
            console.log('  记忆条数: ' + stats.memoryCount);
            console.log('  实体数量: ' + stats.entityCount);
            console.log('  关系数量: ' + stats.relationCount);
            console.log('');
            break;

          case '/skills':
            console.log(chalk.cyan('
=== 内置技能 ==='));
            for (const [name, skill] of agent.skills.skills) {
              console.log('  ' + chalk.bold(name) + ' - ' + skill.description);
            }
            console.log(chalk.cyan('
=== MCP 工具 ==='));
            for (const [key, value] of agent.mcp.tools) {
              console.log('  ' + chalk.bold(key) + ' - ' + (value.tool.description || '').substring(0, 60));
            }
            console.log('');
            break;

          case '/clear':
            agent.conversationHistory = [];
            console.log(chalk.green('对话历史已清除'));
            break;

          case '/help':
            printBanner();
            break;

          default:
            console.log(chalk.red('未知命令: ' + trimmed));
            break;
        }

        prompt();
        return;
      }

      // 处理普通对话
      try {
        const response = await agent.run(trimmed);
        console.log('
' + chalk.bold.green('Resonix> ') + response + '
');
      } catch (error) {
        console.error(chalk.red('
错误: ' + error.message + '
'));
      }

      prompt();
    });
  };

  prompt();

  // 优雅退出
  process.on('SIGINT', async () => {
    console.log(chalk.yellow('
正在关闭...'));
    await agent.shutdown();
    console.log(chalk.green('再见!'));
    process.exit(0);
  });
}

main().catch(console.error);

