  /**
   * 初始化 Agent
   */
  async init() {
    this.logger.info('正在初始化 Resonix Agent...');

    // 连接所有 MCP 服务器
    await this.mcp.connectAll();

    // 初始化记忆系统
    await this.memory.init();

    // 注册内置技能
    this.skills.registerBuiltinSkills();

    // 加载历史记忆
    const memories = await this.memory.recallRecent(10);
    if (memories.length > 0) {
      this.logger.info('已加载 ' + memories.length + ' 条历史记忆');
    }

    this.logger.success('Resonix Agent 初始化完成!');
    this._printStatus();
  }

  /**
   * 运行 Agent 主循环
   */
  async run(userMessage) {
    // 添加用户消息到历史
    this.conversationHistory.push({
      role: 'user',
      content: userMessage
    });

    // 检查是否需要先回忆相关记忆
    const relevantMemories = await this.memory.search(userMessage);
    if (relevantMemories.length > 0) {
      const memoryContext = '相关记忆:\n' + relevantMemories.map(m => '- ' + m.content).join('\n');
      this.conversationHistory.push({
        role: 'system',
        content: memoryContext
      });
    }

    let iteration = 0;
    let finalResponse = '';

    while (iteration < this.maxIterations) {
      iteration++;

      try {
        // 获取 MCP 工具列表
        const mcpTools = this.mcp.getToolsAsOpenAIFormat();

        // 调用 LLM
        const response = await this.llm.chat.completions.create({
          model: this.model,
          messages: [
            { role: 'system', content: this.systemPrompt },
            ...this.conversationHistory
          ],
          tools: mcpTools.length > 0 ? mcpTools : undefined,
          tool_choice: mcpTools.length > 0 ? 'auto' : undefined,
          temperature: 0.7,
          max_tokens: 4096
        });

        const message = response.choices[0].message;
        this.conversationHistory.push(message);

        // 如果没有工具调用，返回最终响应
        if (!message.tool_calls || message.tool_calls.length === 0) {
          finalResponse = message.content;
          break;
        }

        // 处理工具调用
        for (const toolCall of message.tool_calls) {
          const toolName = toolCall.function.name;
          const toolArgs = JSON.parse(toolCall.function.arguments);

          this.logger.toolCall(toolName, toolArgs);

          try {
            // 解析服务器名和工具名
            const [serverName, ...rest] = toolName.split('__');
            const actualToolName = rest.join('__');

            let result;
            // 优先使用 MCP 工具
            if (this.mcp.clients.has(serverName)) {
              result = await this.mcp.callTool(serverName, actualToolName, toolArgs);
            } else {
              // 尝试内置技能
              result = await this.skills.execute(toolName, toolArgs);
            }

            const resultStr = typeof result === 'string' ? result : JSON.stringify(result);
            this.logger.toolResult(toolName, resultStr);

            this.conversationHistory.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              content: resultStr
            });

            // 重要结果存入记忆
            if (this._isWorthRemembering(toolName, resultStr)) {
              await this.memory.remember({
                type: 'tool_result',
                tool: toolName,
                query: userMessage,
                result: resultStr.substring(0, 500)
              });
            }

          } catch (error) {
            this.logger.error('工具调用失败 ' + toolName + ': ' + error.message);
            this.conversationHistory.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              content: '错误: ' + error.message
            });
          }
        }

      } catch (error) {
        this.logger.error('LLM 调用失败: ' + error.message);
        finalResponse = '抱歉，处理时出现错误: ' + error.message;
        break;
      }
    }

    if (iteration >= this.maxIterations) {
      finalResponse = '已达到最大迭代次数，任务可能未完全完成。';
    }

    // 保存对话到记忆
    await this.memory.remember({
      type: 'conversation',
      user: userMessage,
      assistant: finalResponse
    });

    return finalResponse;
  }

  /**
   * 判断结果是否值得记忆
   */
  _isWorthRemembering(toolName, result) {
    const memorableTools = [
      'file_write',
      'shell_execute',
      'code_execute'
    ];
    return memorableTools.some(t => toolName.startsWith(t));
  }

  /**
   * 打印状态
   */
  _printStatus() {
    const status = this.mcp.getStatus();
    console.log('\n' + chalk.cyan('========================================'));
    console.log(chalk.cyan('  Resonix Agent 状态面板'));
    console.log(chalk.cyan('========================================'));
    for (const [name, info] of Object.entries(status)) {
      const icon = info.status === 'connected' ? chalk.green('OK') : chalk.red('FAIL');
      console.log('  ' + icon + ' ' + chalk.bold(name) + ' (' + info.tools + ' tools) - ' + info.description);
    }
    console.log(chalk.cyan('========================================') + '\n');
  }

  /**
   * 关闭 Agent
   */
  async shutdown() {
    this.logger.info('正在关闭 Resonix Agent...');
    await this.mcp.disconnectAll();
    await this.memory.close();
    this.logger.success('Resonix Agent 已关闭');
  }
}

