    `).all('%' + query + '%', limit);

    // 更新访问计数
    for (const r of results) {
      this.db.prepare(`
        UPDATE memories SET accessed_at = CURRENT_TIMESTAMP, access_count = access_count + 1
        WHERE id = ?
      `).run(r.id);
    }

    return results.map(r => ({
      id: r.id,
      type: r.type,
      content: r.content,
      importance: r.importance,
      createdAt: r.created_at
    }));
  }

  /**
   * 获取最近记忆
   */
  async recallRecent(limit = 10) {
    return this.db.prepare(`
      SELECT * FROM memories 
      ORDER BY created_at DESC 
      LIMIT ?
    `).all(limit).map(r => ({
      id: r.id,
      type: r.type,
      content: r.content,
      importance: r.importance,
      createdAt: r.created_at
    }));
  }

  /**
   * 获取重要记忆
   */
  async recallImportant(limit = 10) {
    return this.db.prepare(`
      SELECT * FROM memories 
      ORDER BY importance DESC, created_at DESC 
      LIMIT ?
    `).all(limit).map(r => ({
      id: r.id,
      type: r.type,
      content: r.content,
      importance: r.importance,
      createdAt: r.created_at
    }));
  }

  /**
   * 添加实体
   */
  async addEntity(name, type, description, properties) {
    const id = crypto.randomUUID();
    this.db.prepare(`
      INSERT OR REPLACE INTO entities (id, name, type, description, properties)
      VALUES (?, ?, ?, ?, ?)
    `).run(id, name, type, description, properties ? JSON.stringify(properties) : null);
    return id;
  }

  /**
   * 添加关系
   */
  async addRelation(sourceId, targetId, relationType, properties) {
    const id = crypto.randomUUID();
    this.db.prepare(`
      INSERT INTO relations (id, source_id, target_id, relation_type, properties)
      VALUES (?, ?, ?, ?, ?)
    `).run(id, sourceId, targetId, relationType, properties ? JSON.stringify(properties) : null);
    return id;
  }

  /**
   * 查询实体关系
   */
  async getEntityRelations(entityName) {
    const entity = this.db.prepare('SELECT * FROM entities WHERE name = ?').get(entityName);
    if (!entity) return [];

    return this.db.prepare(`
      SELECT r.*, e.name as target_name, e.type as target_type
      FROM relations r
      JOIN entities e ON r.target_id = e.id
      WHERE r.source_id = ?
    `).all(entity.id);
  }

  /**
   * 删除记忆
   */
  async forget(id) {
    this.db.prepare('DELETE FROM memories WHERE id = ?').run(id);
  }

  /**
   * 清除所有记忆
   */
  async clearAll() {
    this.db.exec('DELETE FROM memories; DELETE FROM entities; DELETE FROM relations;');
  }

  /**
   * 获取统计信息
   */
  getStats() {
    const memoryCount = this.db.prepare('SELECT COUNT(*) as count FROM memories').get().count;
    const entityCount = this.db.prepare('SELECT COUNT(*) as count FROM entities').get().count;
    const relationCount = this.db.prepare('SELECT COUNT(*) as count FROM relations').get().count;
    return { memoryCount, entityCount, relationCount };
  }

  async close() {
    if (this.db) {
      this.db.close();
      console.log('[Memory] 数据库已关闭');
    }
  }
}

