  // === 技能实现 ===

  async _executeCode(args) {
    const { language, code } = args;
    try {
      let cmd;
      switch (language) {
        case 'python':
          cmd = 'python -c "' + code.replace(/"/g, '\"') + '"';
          break;
        case 'javascript':
        case 'js':
          cmd = 'node -e "' + code.replace(/"/g, '\"') + '"';
          break;
        case 'shell':
          cmd = code;
          break;
        default:
          throw new Error('不支持的语言: ' + language);
      }
      const result = execSync(cmd, { timeout: 30000, encoding: 'utf-8' });
      return { success: true, output: result };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _readFile(args) {
    const { path: filePath, encoding } = args;
    try {
      const content = fs.readFileSync(filePath, encoding || 'utf-8');
      return { success: true, content };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _writeFile(args) {
    const { path: filePath, content, encoding } = args;
    try {
      const dir = path.dirname(filePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      fs.writeFileSync(filePath, content, encoding || 'utf-8');
      return { success: true, path: filePath };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _searchFiles(args) {
    const { directory, pattern, content } = args;
    try {
      let cmd = 'dir /s /b';
      if (pattern) cmd += ' "' + directory + '\\' + pattern + '"';
      else cmd += ' "' + directory + '"';

      const result = execSync(cmd, { timeout: 10000, encoding: 'utf-8' });
      let files = result.trim().split('\n').filter(Boolean);

      if (content) {
        const contentRegex = new RegExp(content, 'i');
        files = files.filter(f => {
          try {
            const fileContent = fs.readFileSync(f, 'utf-8');
            return contentRegex.test(fileContent);
          } catch { return false; }
        });
      }

      return { success: true, files: files.slice(0, 50) };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _httpRequest(args) {
    const { url, method, headers, body } = args;
    try {
      const config = {
        method: (method || 'GET').toUpperCase(),
        url,
        headers: headers || {},
        timeout: 30000
      };
      if (body && config.method !== 'GET') {
        config.data = body;
      }
      const response = await axios(config);
      return {
        success: true,
        status: response.status,
        data: typeof response.data === 'string' ? response.data : JSON.stringify(response.data)
      };
    } catch (error) {
      return { success: false, error: error.message, status: error.response?.status };
    }
  }

  async _shellExecute(args) {
    const { command, cwd, timeout } = args;
    try {
      const result = execSync(command, {
        timeout: timeout || 30000,
        encoding: 'utf-8',
        cwd: cwd || process.cwd()
      });
      return { success: true, output: result };
    } catch (error) {
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _dataTransform(args) {
    // 简化的数据转换
    const { input, from_format, to_format } = args;
    try {
      let data;
      if (from_format === 'json') {
        data = JSON.parse(input);
      } else {
        data = input;
      }

      if (to_format === 'json') {
        return { success: true, result: JSON.stringify(data, null, 2) };
      } else if (to_format === 'markdown') {
        if (Array.isArray(data)) {
          let md = '| # | ' + Object.keys(data[0] || {}).join(' | ') + ' |
';
          md += '|---|' + Object.keys(data[0] || {}).map(() => '---').join('|') + '|
';
          data.forEach((row, i) => {
            md += '| ' + (i + 1) + ' | ' + Object.values(row).join(' | ') + ' |
';
          });
          return { success: true, result: md };
        }
        return { success: true, result: '```json
' + JSON.stringify(data, null, 2) + '
```' };
      }

      return { success: true, result: String(data) };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _textAnalyze(args) {
    const { text, analysis_type } = args;
    try {
      switch (analysis_type) {
        case 'stats':
          return {
            success: true,
            result: {
              characters: text.length,
              words: text.split(/\s+/).filter(Boolean).length,
              lines: text.split('
').length,
              sentences: text.split(/[.!?]+/).filter(Boolean).length
            }
          };
        case 'extract_keywords':
          const words = text.toLowerCase().match(/[a-zA-Z一-龥]+/g) || [];
          const freq = {};
          words.forEach(w => { freq[w] = (freq[w] || 0) + 1; });
          const keywords = Object.entries(freq)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 20)
            .map(([word, count]) => ({ word, count }));
          return { success: true, result: keywords };
        default:
          return { success: false, error: '不支持的分析类型: ' + analysis_type };
      }
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _mathCalculate(args) {
    const { expression } = args;
    try {
      // 安全的数学计算 - 只允许数字和基本运算符
      if (!/^[0-9+\-*/().%\s^]+$/.test(expression)) {
        throw new Error('表达式包含不允许的字符');
      }
      const safeExpr = expression.replace(/\^/g, '**');
      const result = Function('"use strict"; return (' + safeExpr + ')')();
      return { success: true, result };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _timeTool(args) {
    const { action, timezone, format: fmt } = args;
    const now = new Date();
    switch (action) {
      case 'now':
        return { success: true, result: now.toISOString(), local: now.toLocaleString('zh-CN') };
      case 'format':
        return { success: true, result: now.toLocaleString('zh-CN', { timeZone: timezone }) };
      default:
        return { success: false, error: '不支持的操作: ' + action };
    }
  }

  async _jsonQuery(args) {
    const { data, query } = args;
    try {
      let obj = typeof data === 'string' ? JSON.parse(data) : data;
      const parts = query.split('.');
      for (const part of parts) {
        if (obj[part] !== undefined) {
          obj = obj[part];
        } else {
          return { success: false, error: '路径不存在: ' + part };
        }
      }
      return { success: true, result: obj };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  // ==========================================
  // Data Analysis 技能实现
  // 通过调用独立 Python 脚本执行，避免 eval/exec
  // ==========================================

  /**
   * 通用 Python 脚本执行器 - 仅用于 data-analysis 模块
   * 调用 scripts/ 目录下的预定义脚本，不执行任意代码
   */
  _runDataScript(scriptName, args) {
    const scriptPath = path.join(process.cwd(), 'scripts', scriptName);
    const argsJson = JSON.stringify(args);
    // 使用临时文件传递参数，避免命令行注入
    const tmpFile = path.join(process.cwd(), 'data', '.tmp_args.json');
    fs.mkdirSync(path.dirname(tmpFile), { recursive: true });
    fs.writeFileSync(tmpFile, argsJson, 'utf-8');
    try {
      const result = execSync(
        'python "' + scriptPath + '" "' + tmpFile + '"',
        { timeout: 60000, encoding: 'utf-8', cwd: process.cwd() }
      );
      // 清理临时文件
      try { fs.unlinkSync(tmpFile); } catch {}
      return JSON.parse(result);
    } catch (error) {
      try { fs.unlinkSync(tmpFile); } catch {}
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _excelRead(args) {
    return this._runDataScript('excel_read.py', args);
  }

  async _dataClean(args) {
    return this._runDataScript('data_clean.py', args);
  }

  async _dataAnalyze(args) {
    return this._runDataScript('data_analyze.py', args);
  }

  async _dataVisualize(args) {
    return this._runDataScript('data_visualize.py', args);
  }

  async _reportGenerate(args) {
    return this._runDataScript('report_generate.py', args);
  }

  // ==========================================
  // Academic Research (ARS) 技能实现
  // 通过调用独立 Python 脚本执行
  // ==========================================

  /**
   * 通用 Python 脚本执行器 - 用于 ARS 模块
   */
  _runARSScript(scriptName, args) {
    const scriptPath = path.join(process.cwd(), 'scripts', scriptName);
    const argsJson = JSON.stringify(args);
    const tmpFile = path.join(process.cwd(), 'data', '.tmp_ars_args.json');
    fs.mkdirSync(path.dirname(tmpFile), { recursive: true });
    fs.writeFileSync(tmpFile, argsJson, 'utf-8');
    try {
      const result = execSync(
        'python "' + scriptPath + '" "' + tmpFile + '"',
        { timeout: 60000, encoding: 'utf-8', cwd: process.cwd() }
      );
      try { fs.unlinkSync(tmpFile); } catch {}
      return JSON.parse(result);
    } catch (error) {
      try { fs.unlinkSync(tmpFile); } catch {}
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _arsConferenceTemplates(args) {
    return this._runARSScript('ars_conference_templates.py', args);
  }

  async _arsCitationVerifier(args) {
    return this._runARSScript('ars_citation_verifier.py', args);
  }

  /**
   * 获取所有技能的 OpenAI 工具格式
   */
  getToolsAsOpenAIFormat() {
    const tools = [];
    for (const [name, skill] of this.skills) {
      tools.push({
        type: 'function',
        function: {
          name: 'skill__' + name,
          description: skill.description,
          parameters: skill.parameters
        }
      });
    }
    return tools;
  }
}

